$_MODULE['<{retractationcommande}prestashop>order-detail_2cec369315350f7bdd5ed0f7c762be97'] = 'Withdraw';
$_MODULE['<{retractationcommande}prestashop>demande_a54afcca3ecc3d5b4891b1a75c73192d'] = 'Order not found or access not authorised.';
$_MODULE['<{retractationcommande}prestashop>demande_ae6c41ce3d6f31f73f9d143bcae0f6b2'] = 'This order is no longer eligible for withdrawal (legal period expired or products already in the process of withdrawal).';
$_MODULE['<{retractationcommande}prestashop>demande_3a6a3681876ab1e4c55fdecb70fab698'] = 'The message contains characters that are not allowed.';
$_MODULE['<{retractationcommande}prestashop>demande_0f9a15225078e2688ee78b984640f46d'] = 'Requested quantity exceeds the quantity available for withdrawal.';
$_MODULE['<{retractationcommande}prestashop>demande_36c075970e7709b21dc06b19cb75c19e'] = 'Select at least one product to withdraw.';
$_MODULE['<{retractationcommande}prestashop>demande_b0998d501f75050aa4045d17399c25d0'] = 'Unable to save the request. Please contact customer service.';
$_MODULE['<{retractationcommande}prestashop>demande_9914a2c75cdd71876e656e7621e47300'] = 'Your withdrawal has been registered under reference %s. An acknowledgment of receipt has been sent to you by email. Our customer service will verify your request and send you the return procedure.';
$_MODULE['<{retractationcommande}prestashop>demande_049d1d68c945230da39359dbd32e1d48'] = 'Your withdrawal has been registered under reference %s. An acknowledgment of receipt has been sent to you by email. As your order has already been shipped, you may refuse the parcel on delivery or, if you receive it, follow the return procedure that our customer service will send you.';
$_MODULE['<{retractationcommande}prestashop>demande_f49c93cbb2dab9d8c4b41d7e8a0f346d'] = 'Your withdrawal has been registered under reference %s. An acknowledgment of receipt has been sent to you by email. As your order has not yet been shipped, no product return will be necessary: after verification, the shipment will be cancelled and you will be refunded.';
$_MODULE['<{retractationcommande}prestashop>demande_5a06e6b127a7d1baaf18d35bde389969'] = 'Our customer service will verify the eligibility of your request (14-day legal period, exclusions under article L221-28). If it is compliant, the return procedure will be sent to you by email, then the refund will be made no later than 14 days after recovery of the goods or receipt of proof of shipment. Please do not return the product before receiving the return procedure.';
$_MODULE['<{retractationcommande}prestashop>demande_b91f8258aeb37ba358b04427913bd6b1'] = 'To check: 14-day period, legal exclusions (art. L221-28), products already returned.';
$_MODULE['<{retractationcommande}prestashop>demande_869cbd236cf583ec668d9f90469f561c'] = 'Your order has already been shipped and is in transit. You may refuse the parcel on delivery; if you receive it, do not open it and wait for the return procedure that our customer service will send you after verification. The refund will be made no later than 14 days after recovery of the goods or receipt of proof of their return.';
$_MODULE['<{retractationcommande}prestashop>demande_e32237222087921238a826c436916179'] = 'ORDER SHIPPED (in transit) — the parcel has left: plan for a parcel refusal or a return. To check: legal exclusions (art. L221-28). The 14-day period will only start at delivery.';
$_MODULE['<{retractationcommande}prestashop>demande_ba6e3c755dec44b85c76f4e9e919450b'] = 'As your order has not yet been shipped, no product return will be necessary. After verification of your request by our customer service, the shipment will be cancelled and the full amount paid will be refunded to you no later than 14 days after your request, using the same means of payment (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>demande_ecbc815f858a7d4a0ff0fe67f6eea2a3'] = 'ORDER NOT SHIPPED — cancellation before shipment: no product return expected. To check: legal exclusions (art. L221-28). Remember to block the shipment before validating.';
$_MODULE['<{retractationcommande}prestashop>demande_00e9581137cc9fcce29afdb92e74d13a'] = 'Shipped, in transit';
$_MODULE['<{retractationcommande}prestashop>demande_5f0d073c461f238ea2622dc70766a38f'] = 'Not shipped at the time of the request';
$_MODULE['<{retractationcommande}prestashop>demande_a860874ff76e61887b36e2c13ab146f1'] = 'Acknowledgment of receipt of your withdrawal request';
$_MODULE['<{retractationcommande}prestashop>demande_cb082ed668c8c616513cef755d589f79'] = 'New withdrawal request to verify';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_f9598f3efc5b2b93bd2643a72a431969'] = 'You have 14 days to withdraw from the contract, without having to give a reason (art. L221-18 of the French Consumer Code). The period starts the day after delivery of the goods (or the day after the contract is concluded for a service). If it ends on a Saturday, Sunday or public holiday, it is extended to the next working day.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_5aea05f1d39a0423c4b25484d0bfbbfb'] = 'goods unsealed after delivery that cannot be returned for reasons of hygiene or health protection;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_44fc39e9f72aa3cbac9747645c8e3f28'] = 'digital content supplied without a physical medium whose performance has begun with your consent;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_b6ecb45483f4b3b9de90c6b3d7e2086c'] = 'goods inseparably mixed with other items after delivery.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ea20d48829cf42f58a7ba2e8d2ccab41'] = 'Our customer service will review your request and send you the return procedure by email. Please do not send the item(s) back before you have received it, and return the goods complete and in their original condition.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_c7c5d3c287928163baae28c1c94ffb57'] = 'Order already shipped: you may refuse the parcel when it is presented. If you receive it, do not open it and follow the return procedure our customer service will send you. Return the goods complete and in their original condition.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ad7b6dc631e43afbd497f23ef43ab78c'] = 'Order not shipped: no product return will be necessary. Our customer service will review your request, cancel the shipment and issue the refund.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_7d1c4561845314f94d407ede430c9a60'] = 'If you believe your request has not been handled in accordance with the regulations, you may contact our customer service, then refer the matter free of charge to a consumer ombudsman (art. L612-1 of the French Consumer Code).';
