$_MODULE['<{retractationcommande}prestashop>pdf-accuse_afe72c2b21191da1897798ce03f6bb0a'] = 'In accordance with article L221-21 of the French Consumer Code, we acknowledge receipt of your withdrawal request';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_1d4a33337550b1d60f155dc7dca2ecef'] = 'Your request will be reviewed by our customer service (compliance with the legal period, exclusions set out in article L221-28 of the French Consumer Code). If it complies, the return procedure will be sent to you by email. Please do not send the item(s) back before you have received it. The refund will be issued no later than 14 days after recovery of the goods or receipt of proof of dispatch, using the same means of payment as the one used for the order (art. L221-24). Direct return shipping costs remain payable by you (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_08a4255076063ff093392602b74f2dde'] = 'As your order had already been shipped when you submitted your request, you may refuse the parcel when it is presented or, if you receive it, follow the return procedure our customer service will send you after review (exclusions set out in article L221-28 of the French Consumer Code). The refund will be issued no later than 14 days after recovery of the goods or receipt of proof of their return, using the same means of payment as the one used for the order (art. L221-24). Direct return shipping costs remain payable by you (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_ecd429447c2c5c11827567f6c066424e'] = 'As your order had not yet been shipped when you submitted your request, no product return will be necessary. After review by our customer service (exclusions set out in article L221-28 of the French Consumer Code), the shipment will be cancelled and all sums paid will be refunded to you no later than 14 days after your request, using the same means of payment as the one used for the order (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>formulaire_6fd32367e8a01032b6c24770df162923'] = 'In accordance with articles L221-18 et seq. of the French Consumer Code, you have';
$_MODULE['<{retractationcommande}prestashop>formulaire_04f75f9992b78fd3affb67c8db773850'] = 'from the day after delivery to withdraw, without having to give a reason. If this period ends on a Saturday, Sunday or public holiday, it is extended to the next working day.';
