$_MODULE['<{retractationcommande}prestashop>formulaire_24eabc929ddb3eb38fd6cf81b5ffa805'] = 'Enter the email address used for the order and the order reference (shown on your confirmation email).';
$_MODULE['<{retractationcommande}prestashop>formulaire_b414b1464d384d5b827c361fec76cc8f'] = 'This order is not (or no longer) eligible for online withdrawal: legal period expired, request already submitted or order not concerned. For any question, please contact our customer service.';
$_MODULE['<{retractationcommande}prestashop>formulaire_dbad83ecebaf719a4dd60e45bbec0e03'] = 'The right of withdrawal does not apply to certain contracts (art. L221-28 of the French Consumer Code: made-to-measure or personalised goods, perishable goods, goods unsealed for hygiene reasons, etc.). Once submitted, your request is reviewed by our customer service, which sends you the return procedure. The refund is issued no later than 14 days after recovery of the goods or receipt of proof of dispatch, using the same means of payment. Return shipping costs remain payable by you.';
$_MODULE['<{retractationcommande}prestashop>modal_30e7d78f70861e0332aa4cbb81a2fcd3'] = 'Return possible';
