$_MODULE['<{retractationcommande}prestashop>modal_217c9acbe7666448db6b898ca2ab6bef'] = 'Confirm the return request';
$_MODULE['<{retractationcommande}prestashop>modal_810a3d382ec684c35146d332e396e1c1'] = 'By confirming, your withdrawal request is sent to our customer service and an acknowledgement of receipt is sent to you by email with a PDF copy (art. L221-21 of the French Consumer Code). After the eligibility review (legal period, exclusions in art. L221-28), the return procedure will be sent to you — please do not send the products back before you have received it. The refund is issued no later than 14 days after recovery of the goods or receipt of proof of dispatch (delivery costs included for a full withdrawal, pro rata otherwise). Return shipping costs remain payable by you.';
$_MODULE['<{retractationcommande}prestashop>modal_abeaaec30c11df72742faf07dc857200'] = 'By confirming, your withdrawal request is sent to our customer service and an acknowledgement of receipt is sent to you by email with a PDF copy (art. L221-21 of the French Consumer Code). As your order has already been shipped, you may refuse the parcel when it is presented; if you receive it, do not open it and follow the return procedure our customer service will send you. The refund is issued no later than 14 days after recovery of the goods or receipt of proof of their return. Return shipping costs remain payable by you.';
$_MODULE['<{retractationcommande}prestashop>modal_ad52dcb5592e9f635028ab04aaf1fcec'] = 'By confirming, your withdrawal request is sent to our customer service and an acknowledgement of receipt is sent to you by email with a PDF copy (art. L221-21 of the French Consumer Code). As your order has not yet been shipped, no product return will be necessary: after review (exclusions in art. L221-28), the shipment will be cancelled and all sums paid will be refunded to you no later than 14 days after your request, using the same means of payment.';
$_MODULE['<{retractationcommande}prestashop>modal_c729999c38ef8dd3345cdcab0b29495a'] = 'By confirming, your return request is sent to our customer service, which reviews it against our return conditions and sends you the procedure to follow. Please do not send the products back before you have received it.';
