$_MODULE['<{retractationcommande}prestashop>demande_afeb49c5004af7a5c3fb574552f8524f'] = 'Your return request has been registered under reference %s. A confirmation has been sent to you by email. Our customer service will review your request and send you the return procedure.';
$_MODULE['<{retractationcommande}prestashop>demande_81e83ee9703e6ffae031e8e2eded2a35'] = 'Your withdrawal has been registered under reference %s. An acknowledgement of receipt has been sent to you by email. As your order has not yet been shipped, no product return will be necessary: after review, the shipment will be cancelled and you will be refunded.';
$_MODULE['<{retractationcommande}prestashop>demande_9f4095725b4314c97caefc7cc2bf5f14'] = 'Our customer service will review your request against our return conditions. If it is accepted, the return procedure will be sent to you by email. Please do not send the product back before you have received it.';
$_MODULE['<{retractationcommande}prestashop>demande_50b76525f8ad63640702a5c148f36e5c'] = 'COMMERCIAL RETURN (customer group rules) — to be reviewed against your return conditions, not against the right of withdrawal.';
$_MODULE['<{retractationcommande}prestashop>demande_1808dee14b88dac577384c0f22c5926e'] = 'Our customer service will review whether your request is eligible (14-day legal period, exclusions in article L221-28). If it complies, the return procedure will be sent to you by email, then the refund will be issued no later than 14 days after recovery of the goods or receipt of proof of dispatch. Please do not send the product back before you have received the return procedure.';
$_MODULE['<{retractationcommande}prestashop>demande_5b3514e1541cfd0318e31c694a2aa909'] = 'Your order has already been shipped and is in transit. You may refuse the parcel when it is presented; if you receive it, do not open it and wait for the return procedure our customer service will send you after review. The refund will be issued no later than 14 days after recovery of the goods or receipt of proof of their return.';
$_MODULE['<{retractationcommande}prestashop>demande_fef84e875177fa1aa360bef363059b72'] = 'ORDER SHIPPED (in transit) — the parcel has left: plan for a refused parcel or a return. To check: legal exclusions (art. L221-28). The 14-day period will only start on delivery.';
$_MODULE['<{retractationcommande}prestashop>demande_e1a266b5d2d6ad5263f80d3a3cb670b3'] = 'As your order has not yet been shipped, no product return will be necessary. After your request has been reviewed by our customer service, the shipment will be cancelled and all sums paid will be refunded to you no later than 14 days after your request, using the same means of payment (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>demande_325727fe2185eac42770ba795f29f428'] = 'ORDER NOT SHIPPED — cancellation before shipping: no product return expected. To check: legal exclusions (art. L221-28). Remember to block the shipment before approving.';
